// wordmark.py:end

const word = useIdentity().alias ? 'monochromish' : 'himanshu'
const { ink: INK, path: WORD_PATH } = WORDMARKS[word]

// light radius in font units (the x-height is 500)
const LIGHT = 620

const root = ref<HTMLElement>()
const canvas = ref<HTMLCanvasElement>()
const ready = ref(false)

let ctx: CanvasRenderingContext2D | null = null
let frame: ImageData | null = null
let fb: Uint32Array | null = null
let base: Uint32Array | null = null
let inside: Uint8Array | null = null
let cols = 0
let rows = 0
let unit = 0
let ink = 0
let soft = 0
let lit = 0
let sizer: ResizeObserver | undefined
let themes: MutationObserver | undefined

const light = { x: { x: 0, v: 0 }, y: { x: 0, v: 0 }, open: { x: 0, v: 0 } }
const target = { x: 0, y: 0, open: 0 }
let client: { x: number, y: number } | null = null
let enabled = false
let raf = 0
let last = 0

function readColors() {
  ink = readColor(root.value!, '--ink')
  soft = readColor(root.value!, '--ink-3')
  lit = readColor(root.value!, '--accent')
}

function rasterize() {
  const off = document.createElement('canvas')
  off.width = cols
  off.height = rows
  const octx = off.getContext('2d', { willReadFrequently: true })!
  octx.setTransform(unit, 0, 0, unit, -INK.x * unit, -INK.y * unit)
  octx.fill(new Path2D(WORD_PATH))
  const px = octx.getImageData(0, 0, cols, rows).data
  inside = new Uint8Array(cols * rows)
  for (let i = 0; i < inside.length; i++) inside[i] = px[i * 4 + 3]! > 127 ? 1 : 0
}

function paintBase() {
  if (inside) base = rampFill(inside, cols, rows, ink, soft)
}

function draw() {
  if (!ctx || !frame || !fb || !base || !inside) return
  fb.set(base)
  const a = Math.min(1, Math.max(0, light.open.x))
  if (a > 0.01) {
    const r = LIGHT * unit * (0.6 + 0.4 * a)
    const cx = light.x.x, cy = light.y.x
    const x0 = Math.max(0, Math.floor(cx - r)), x1 = Math.min(cols - 1, Math.ceil(cx + r))
    const y0 = Math.max(0, Math.floor(cy - r)), y1 = Math.min(rows - 1, Math.ceil(cy + r))
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        const i = y * cols + x
        if (!inside[i]) continue
        const f = 1 - Math.hypot(x + 0.5 - cx, y + 0.5 - cy) / r
        if (a * f > bayer(x, y)) fb[i] = lit
      }
    }
  }
  ctx.putImageData(frame, 0, 0)
}

function fit(width: number) {
  const dpr = devicePixelRatio || 1
  // 4 px cells like the lagoon, finer on a narrow column so strokes keep 3+ cells
  const cell = Math.min(4, Math.max(2, Math.floor(width / 156)))
  const k = Math.max(2, Math.round(cell * dpr))
  const c = Math.max(1, Math.round(width * dpr / k))
  const el = canvas.value!
  if (c !== cols) {
    cols = c
    unit = cols / INK.width
    rows = Math.max(1, Math.round(INK.height * unit))
    el.width = cols
    el.height = rows
    ctx = el.getContext('2d')!
    frame = ctx.createImageData(cols, rows)
    fb = new Uint32Array(frame.data.buffer)
    rasterize()
    paintBase()
    draw()
  }
  el.style.width = `${cols * k / dpr}px`
  el.style.height = `${rows * k / dpr}px`
}

function aim(cx: number, cy: number) {
  const box = canvas.value!.getBoundingClientRect()
  target.x = (cx - box.left) / box.width * cols
  target.y = (cy - box.top) / box.height * rows
  return cx >= box.left && cx <= box.right && cy >= box.top && cy <= box.bottom
}

function step(t: number) {
  const dt = Math.min(0.05, (t - last) / 1000)
  last = t
  // underdamped
  stepSpring(light.x, target.x, dt, 0.42, 0.72)
  stepSpring(light.y, target.y, dt, 0.42, 0.72)
  stepSpring(light.open, target.open, dt, target.open ? 0.34 : 0.26, 1)
  draw()
  const tol = 0.05
  const moving = !springAtRest(light.x, target.x, tol) || !springAtRest(light.y, target.y, tol) || !springAtRest(light.open, target.open)
  raf = moving ? requestAnimationFrame(step) : 0
}

function kick() {
  if (raf) return
  last = performance.now()
  raf = requestAnimationFrame(step)
}

function onEnter(e: PointerEvent) {
  if (!enabled || e.pointerType === 'touch' || !cols) return
  aim(e.clientX, e.clientY)
  if (light.open.x < 0.05) {
    light.x.x = target.x
    light.y.x = target.y
    light.x.v = light.y.v = 0
  }
  client = { x: e.clientX, y: e.clientY }
  target.open = 1
  kick()
}

function onMove(e: PointerEvent) {
  if (!enabled || e.pointerType === 'touch' || !cols) return
  client = { x: e.clientX, y: e.clientY }
  aim(e.clientX, e.clientY)
  target.open = 1
  kick()
}

function onLeave() {
  client = null
  target.open = 0
  kick()
}

function onScroll() {
  if (!client) return
  if (!aim(client.x, client.y)) onLeave()
  else kick()
}

onMounted(() => {
  readColors()
  sizer = new ResizeObserver(([entry]) => {
    fit(entry!.contentRect.width)
    ready.value = true
  })
  try {
    sizer.observe(root.value!, { box: 'device-pixel-content-box' })
  }
  catch {
    sizer.observe(root.value!)
  }
  themes = new MutationObserver(() => {
    readColors()
    paintBase()
    draw()
  })
  themes.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] })
  enabled = matchMedia('(hover: hover) and (pointer: fine)').matches && !matchMedia('(prefers-reduced-motion: reduce)').matches
  if (enabled) window.addEventListener('scroll', onScroll, { passive: true })
})

onBeforeUnmount(() => {
  cancelAnimationFrame(raf)
  sizer?.disconnect()
  themes?.disconnect()
  window.removeEventListener('scroll', onScroll)
})

const fallback = `<svg viewBox="${INK.x} ${INK.y} ${INK.width} ${INK.height}" aria-hidden="true"><path d="${WORD_PATH}" fill="currentColor"/></svg>`
</script>

<template>
  <div
    ref="root"
    class="wordmark"
    role="img"
    :aria-label="word"
    :style="{ aspectRatio: `${INK.width} / ${INK.height}` }"
    @pointerenter="onEnter"
    @pointermove="onMove"
    @pointerleave="onLeave"
  >
    <canvas ref="canvas" :class="{ ready }" />
    <noscript v-html="fallback" />
  </div>
</template>

<style scoped>
.wordmark {
  position: relative;
  width: 100%;
  color: var(--ink);
}
canvas {
  position: absolute;
  left: 0;
  bottom: 0;
  display: block;
  image-rendering: pixelated;
  opacity: 0;
  transition: opacity 200ms var(--ease-out);
}
canvas.ready {
  opacity: 1;
}
.wordmark :deep(svg) {
